	let url = "";
	if(!titleStr || titleStr.length == 0){
		T(java, "请输入标题！！\n\n\n\n");
		return;
	}
	if(type == "discover") {
		let status = String(infoMap["state"]);
		let order = String(infoMap["order"]);
		let cate = String(infoMap["cate"]);
		let offset = String(infoMap["起始页数"]);
		url = initDiscoverUrlUD(status, order, cate, offset);
