//获取源域名
const getHostUrls = (java, source) => {
	T(java,"\n\n开始获取可切换域名！\n\n")
	let args = getArgs(java, source);
	let getHosts = [];
	let tempContent = "";
	for(let n in fetchHostsUrls){
		T(java,`\n\n发布页解析中【${n}/${fetchHostsUrls.length}】\n\n请耐心等待！！`)
		let url = fetchHostsUrls[n];
		try{
			tempContent = java.webView("", url, "", false);
		}catch(e){
			tempContent = "";
		}
		if(java.getString("#imageMap@html", tempContent) != ""){
			tempContent = java.getString("tag.area@html", tempContent);
		} else if(java.getString("div.error_page@html", tempContent) != ""){
			tempContent = java.getString("tag.h1@tag.a@html", tempContent);
		} else {
			tempContent = "";
		}
		let l = java.getStringList("a@href&&area@href##\/?$##\/", tempContent);
		getHosts = getHosts.concat(l);
	}
	let addObj = {};
	let countA = 0;
	for(let j in getHosts){
		let name = String(getHosts[j]).replace(/^https?\:\/\/(w*\.)?([^\/]+)\/?$/,"$2");
		if(!args.hosts[name] && !addObj[name]){
			addObj[name] = getHosts[j];
			countA ++;
		}
	}
	let addHosts = {};
	let counting = 1;
	for(let key in addObj){
		T(java,`\n\n地址验证中【${counting++}／${countA}】\n\n请耐心等待！！\n\n！`);
		if(!checkBookAddr(java, source, addObj[key])){
			continue;
		}
		addHosts[key] = {
			"url" : addObj[key],
			"token" : "",
			"lastTest" : -1,
			"delay" : -1,
			"err" : ""
		};
	}
	counting = 0;
	for(let o in addHosts){
		args.hosts[o] = addHosts[o];
		args.hostArr.push(o + " " + disconnectedMark[0]);
		counting++;
	}
	args.hostArr.sort();
	L(java,4,"新获取到的源：\n" + JSON.stringify(addHosts, "\t"));
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
	T(java,`\n\n域名获取完成！\n\n新增${counting}个域名！`);
}
//批量测试所有域名连接状态
const testConnet = (java, source, infoMap) => {
	let args = getArgs(java,source);
	T(java,"\n\n开始测试各域名状态及连接延迟\n\n请耐心等候\n\n。。。\n\n\n");
	let delIndex = [];
	let newDomain = "";
	for (let i in args.hostArr){
		if(i > 0){
			T(java,`\n\n连接测试中【${i}/${args.hostArr.length}】\n\n请耐心等候\n\n。。。\n\n\n`);
		}
		let o = args.hostArr[i].split(" ")[0];
		L(java,4, "开始测试 " + args.hosts[o].url);
		args.hosts[o].lastTest = Date.now();
		let respons = java.connect(args.hosts[o].url, {}, speedGrading*(speedMark.length + 3));
		args.hosts[o].delay = respons.callTime();
		L(java,4,"测试延迟 " + args.hosts[o].delay) + " 毫秒";
		if(args.hosts[o].delay > 0){
			args.hosts[o].err = "";
			let delayStatus = parseInt(args.hosts[o].delay / speedGrading);
			let mark = speedMark[delayStatus];
			let delay = args.hosts[o].delay;
			let name = args.hostArr[i].split(" ")[0];
			if(delayStatus < speedMark.length){
				args.hostArr[i] = `${name} ${mark}${delay}`;
			} else {
				args.hostArr[i] = `${name} ${disconnectedMark[1]}${delay}`;
			}
		} else {
			switch(args.hosts[o].delay){
				case 0:
					args.hosts[o].err = "网页无法访问";
					break;
				case -1:
					args.hosts[o].err = "超过设定时间";
					break;
				case -2:
					args.hosts[o].err = "超时";
					break;
				case -3:
					args.hosts[o].err = "域名错误";
					break;
				case -4:
					args.hosts[o].err = "连接被拒绝";
					break;
				case -5:
					args.hosts[o].err = "连接被重置";
					break;
				case -6:
					args.hosts[o].err = "SSL证书错误";
					break;
				case -7:
					args.hosts[o].err = "其它错误";
					break;
				default:
					args.hosts[o].err = "未收录的错误";
			}
			args.hostArr[i] = args.hostArr[i].split(" ")[0] + " " + disconnectedMark[2];
		}
		let redirectUrl = String(respons.raw().request().url().toString());
		let rName = redirectUrl.replace(/^https?\:\/\/w*\.([^\/]+)\/?$/, "$1");
		if(args.hosts[o].url != redirectUrl){
			L(java,4,`域名${args.hosts[o].url}被重定向到了${redirectUrl}！！`);
			if(args.domain.split(" ")[0] == o){
				L(java,4,`当前使用域名被重定向，设置为重定向后域名${redirectUrl}！！`);
				newDomain = rName;
			}
			if(args.hosts[rName]){
				L(java,4,`重定向域名${redirectUrl}已在配置中，不需要新增！！`);
			}else{
				L(java,4,`新增重定向后域名${redirectUrl}！！`);
				args.hosts[rName] = {
					"url" : redirectUrl,
					"token" : "",
					"lastTest" : args.hosts[o].lastTest,
					"delay" : args.hosts[o].delay,
					"err" : ""
				};
				args.hostArr.push(rName + " " + args.hostArr[i].split(" ")[1]);
			}
			delIndex.push(i);
		}
		if(args.domain.split(" ")[0] == o){
			args.domain = args.hostArr[i];
			infoMap["domain"] = args.domain;
			infoMap.save();
		}
		redirected = false;
	}
	let subfixStr = "";
	if(delIndex.length > 0){
		for(let i = delIndex.length - 1; i >= 0; i--){
			let o = args.hostArr[delIndex[i]].split(" ")[0];
			L(java,4,`删除重定向域名${args.hosts[o].url}！`);
			delete args.hosts[o];
			args.hostArr.splice(delIndex[i], 1);
		}
		subfixStr = `\n\n处理了${delIndex.length}个重定向的域名！！`;
	}
	if(newDomain != ""){
		for(var i in args.hostArr){
			if(args.hostArr[i].split(" ")[0] == newDomain){
				args.domain = args.hostArr[i];
				infoMap["domain"] = args.domain;
				infoMap.save();
			}
		}
	}
	L(java,4,JSON.stringify(args.hosts, null, "\t"));
	T(java,`\n\n测试完成！！！${subfixStr}\n\n\n`)
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
}
