const addHost = (java, source, infoMap) => {
	let args = getArgs(java,source);
	let url = String(infoMap["URL"]).replace(/\/?$/, "");
	if(!url){
		T(java, "\n\n请输入URL！！！");
		return;
	}
	let host = infoMap["protocal"] + "://" + url;
	url = url.replace(/^www\./,"");
	let rsps = null;
	try{
		host = java.toURL(host,"").origin;
	}catch(e){
		T(java, host + "\n\n不是有效的链接！！");
		return;
	}
	host = String(host).replace(/\/?$/,"/");
	if(args.hosts[url]){
		T(java, host + "\n\n已经存在！！");
		return;
	}
	try{
		rsps = java.connect(host + "jilu.php", {}, 2500);
		if(rsps.callTime() <= 0){
			T(java, host + "\n\n无法连接！！");
			return;
		}
		if(!(rsps.code() == 200 && java.getString("h1.page-title@text", rsps.body()) == "您的阅读足迹")){
			T(java, host + "\n\n不是第一版主系列网站！！");
			return;
		}
	}catch(e){
		T(java, host + "\n\n无法连接！！");
		return;
	}
	if(!checkBookAddr(java, source, host)){
		T(java, host + "\n\n与当前书源地址不是一个体系，会导致切换源书籍内容改变，不能添加！！\n\n\n\n");
		return;
	}
	args.hosts[url] = {
		"url" : host,
		"token" : "",
		"lastTest" : -1,
		"delay" : -1,
		"err" : ""
	};
	args.hostArr.push(url + " " + disconnectedMark[0]);
		args.hostArr.sort();
	saveArgs(source, args);
	infoMap["URL"] = "";
	infoMap.save();
	T(java, host + "\n\n添加成功！！");
	java.refreshExplore();
	source.refreshExplore();
}
//删除选中源
const delHost = (java, source, infoMap) => {
	let args = getArgs(java,source);
	let host = String(infoMap["domain"]);
	if(args.hostArr.length < 2){
		T(java, `无法删除源\n\n${host}\n\n这是最后一个源了！\n\n`);
		return;
	}
	let domainName = host.split(" ")[0];
	T(java, `删除源\n\n${host}`);
	for(var i in args.hostArr){
		if(args.hostArr[i] == host){
			delete args.hosts[domainName];
			args.hostArr.splice(i, 1);
			break;
		}
	}
	if(args.domain == host){
		args.domain = args.hostArr[0];
		infoMap["domain"] = args.hostArr[0];
	}
	saveArgs(source, args);
	infoMap.save();
	java.refreshExplore();
	source.refreshExplore();
	T(java, `已删除源\n\n${host}`);
}
