//源变量基础参数名
const argsKeys = ["domain", "keyWord", "order", "state", "offset", "viewMode", "discoverMode", "authors", "UDDiscoverArr", "hostArr", "UDDiscover", "hosts"];
//初始化源变量
const initArgs = () => {
	return  {
		"domain": optionsJson.hosts[0],
		"order": optionsJson.order[0],
		"state": optionsJson.state[0],
		"offset": 1,
		"viewMode": "discover",
		"discoverMode": "discover",
		"authors": defaultAuthors,
		"UDDiscover": {},
		"UDDiscoverArr": [],
		"keyWord": "",
		"hostArr": optionsJson.hosts,
		"hosts": defaultHosts
	};
}
//获取源变量参数
const getArgs = (java, source) => {
	let argsStr = source.getVariable();
	let args;
	if(!argsStr || argsStr == ""){
		TE(java,"重新初始化参数！")
		args = initArgs();
		saveArgs(source, args);
	} else {
		args = JSON.parse(argsStr);
		for (let k in argsKeys) {
			let tmpValue = args[argsKeys[k]];
			if(typeof(tmpValue) == "undefined"){
				TE(java,`参数${argsKeys[k]}不存在，重新初始化！`)
				let newArgs = initArgs();
				for(let key in args){
					if(args[key]){
						newArgs[key] = args[key];
					}
				}
				args = newArgs;
				saveArgs(source,args);
				break;
			}
		}
	}
	return args;
}
//保存参数
const saveArgs = (source, args) => {
	source.setVariable(JSON.stringify(args,null,"\t"));
}
//获取切换的域名
const getHostUrl = (java,source) => {
	let args = getArgs(java,source);
	return args.hosts[args.domain.split(" ")[0]].url;
}
