source.exploreUrl:
@js:
    let result=[],
    push=(title,url,size)=>result.push({
        "title": title,
        "url": url,
        "style": {
            "layout_flexGrow": 1,
            "layout_flexBasisPercent": size
        }
    });
    let bu=source.key+"/cn/comics",
    aj=java.ajax(bu),
    a=org.jsoup.Jsoup.parse(aj);
    let b=a.select('.flex-none [class="group/disclosure"]'),
    s=b.select('[class^="text-sm"]'),
    icons=['🍒','🍊','🥝','🍑','🍅','🍇',];
    push(`🍈全部漫画🍈`,`${bu}<,?page={{page}}>`,1);
    for (i=0;i<s.length;i++){
    	    push(icons[i]+s[i].text()+icons[i],'',1);
    	    let c=b[i].select('[class^="h-10"]');
    	    for (n=1;n<c.length;n++){
    	    	    let url=String(c[n].attr('href'));
    	    	    push(c[n].text(),`${url}<,&page={{page}}>`,0.25);    	    	    	
    	    	};
    };
    JSON.stringify(result);

